"""sheet.py — spreadsheet formula engine (standard library only, Python 3.11)."""

from __future__ import annotations

__all__ = ["Sheet"]

import math
import re
from decimal import Decimal, localcontext

# Error codes
DIV0 = "#DIV/0!"
VALUE_E = "#VALUE!"
REF_E = "#REF!"
NAME_E = "#NAME?"
PARSE_E = "#PARSE!"
CYCLE_E = "#CYCLE!"

ERROR_CODES = {DIV0, VALUE_E, REF_E, NAME_E, PARSE_E, CYCLE_E}

MAX_ROWS = 9999
MAX_COL = ZZ_COL  # placeholder replaced below


# ---------------------------------------------------------------------------
# Reference helpers
# ---------------------------------------------------------------------------

def col_to_num(letters: str) -> int:
    """Excel-style column letters (A..Z, AA..AZ, ..., ZZ) -> 1-based number."""
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n


def num_to_col(n: int) -> str:
    """1-based column number -> Excel-style letters."""
    s = ""
    while n > 0:
        n, rem = divmod(n - 1, 26)
        s = chr(ord("A") + rem) + s
    return s


_REF_RE = re.compile(r"^[A-Za-z]{1,2}[0-9]{1,4}$")


def parse_ref(ref: str) -> tuple[int, int]:
    """Parse a canonical cell reference -> (row, col); raise ValueError if invalid."""
    if not isinstance(ref, str):
        raise ValueError("ref must be a string")
    if not _REF_RE.match(ref):
        raise ValueError(f"invalid reference: {ref!r}")
    letters = ref[: len(ref) - len(ref.lstrip("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"))]
    digits = ref[len(letters):]
    col = col_to_num(letters.upper())
    row = int(digits)
    if row < 1 or row > MAX_ROWS or col < 1 or col > 702:
        raise ValueError(f"invalid reference: {ref!r}")
    return row, col


def canon_ref(ref: str) -> str:
    row, col = parse_ref(ref)
    return f"{num_to_col(col)}{row}"


def _ref_text(row: int, col: int) -> str:
    return f"{num_to_col(col)}{row}"


class _RefOut(Exception):
    """Raised when a reference-shaped token is out of bounds inside a formula."""

    def __init__(self, ref: str):
        self.ref = ref


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

class _Tok:
    __slots__ = ("kind", "text", "value")

    def __init__(self, kind: str, text: str, value=None):
        self.kind = kind
        self.text = text
        self.value = value

    def __repr__(self):  # pragma: no cover
        return f"_Tok({self.kind!r}, {self.text!r})"


_WS = " \t\r\n\f\v"
_NUMBER_RE = re.compile(r"[0-9]+(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?|\.[0-9]+(?:[eE][+-]?[0-9]+)?")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_COMP_OPS = ("<>", "<=", ">=", "=", "<", ">")


def _is_ref_shape(word: str) -> bool:
    if not (1 <= len(word) <= 6):
        return False
    i = 0
    while i < len(word) and word[i].isalpha():
        i += 1
    if i == 0 or i > 2 or i == len(word):
        return False
    digits = word[i:]
    if not digits.isdigit():
        return False
    col = col_to_num(word[:i].upper())
    try:
        row = int(digits)
    except ValueError:
        return False
    return 1 <= row <= MAX_ROWS and 1 <= col <= 702


def tokenize(src: str) -> list[_Tok]:
    toks: list[_Tok] = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c in _WS:
            i += 1
            continue
        if c == '"':
            i += 1
            buf = []
            closed = False
            while i < n:
                if src[i] == '"':
                    if i + 1 < n and src[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                else:
                    buf.append(src[i])
                    i += 1
            if not closed:
                raise _ParseSyntax()
            toks.append(_Tok("string", "".join(buf)))
            continue
        if c.isdigit() or (c == "." and i + 1 < n and src[i + 1].isdigit()):
            m = _NUMBER_RE.match(src, i)
            toks.append(_Tok("number", m.group(0), float(m.group(0))))
            i = m.end()
            continue
        if c.isalpha() or c == "_":
            m = _IDENT_RE.match(src, i)
            word = m.group(0)
            i = m.end()
            up = word.upper()
            if up == "TRUE":
                toks.append(_Tok("bool", word, True))
            elif up == "FALSE":
                toks.append(_Tok("bool", word, False))
            elif _is_ref_shape(word) or _REF_RE.match(word):
                toks.append(_Tok("ref", word.upper()))
            else:
                toks.append(_Tok("ident", word))
            continue
        two = src[i:i + 2]
        if two in ("<>", "<=", ">="):
            toks.append(_Tok("op", two))
            i += 2
            continue
        if c in "=<>+-*/&^(),:!":
            toks.append(_Tok("op", c))
            i += 1
            continue
        raise _ParseSyntax()
    return toks


class _ParseSyntax(Exception):
    pass


# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------

class _Num:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Str:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Bool:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Cell:
    __slots__ = ("ref",)

    def __init__(self, ref):
        self.ref = ref


class _Range:
    __slots__ = ("a", "b")

    def __init__(self, a, b):
        self.a = a
        self.b = b


class _Call:
    __slots__ = ("name", "args")

    def __init__(self, name, args):
        self.name = name
        self.args = args


class _Bin:
    __slots__ = ("op", "l", "r")

    def __init__(self, op, l, r):
        self.op = op
        self.l = l
        self.r = r


class _Un:
    __slots__ = ("op", "x")

    def __init__(self, op, x):
        self.op = op
        self.x = x


class _BadRef:
    __slots__ = ("ref",)

    def __init__(self, ref):
        self.ref = ref


class _BadName:
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

class _Parser:
    def __init__(self, toks: list[_Tok]):
        self.toks = toks
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def next(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        self.i += 1
        return t

    def at_op(self, *ops: str) -> bool:
        t = self.peek()
        return t is not None and t.kind == "op" and t.text in ops

    def expect_op(self, op: str):
        t = self.peek()
        if t is None or t.kind != "op" or t.text != op:
            raise _ParseSyntax()
        self.i += 1

    # comparison level (lowest)
    def parse(self):
        node = self.concat()
        while self.at_op("=", "<>", "<", ">", "<=", ">="):
            op = self.next().text
            node = _Bin(op, node, self.concat())
        return node

    def concat(self):
        node = self.additive()
        while self.at_op("&"):
            self.next()
            node = _Bin("&", node, self.additive())
        return node

    def additive(self):
        node = self.multiplicative()
        while self.at_op("+", "-"):
            op = self.next().text
            node = _Bin(op, node, self.multiplicative())
        return node

    def multiplicative(self):
        node = self.unary()
        while self.at_op("*", "/"):
            op = self.next().text
            node = _Bin(op, node, self.unary())
        return node

    def unary(self):
        if self.at_op("-", "+"):
            op = self.next().text
            return _Un(op, self.unary())
        return self.power()

    def power(self):
        base = self.primary()
        if self.at_op("^"):
            self.next()
            return _Bin("^", base, self.unary())
        return base

    def primary(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        if t.kind == "number":
            self.next()
            return _Num(t.value)
        if t.kind == "string":
            self.next()
            return _Str(t.value)
        if t.kind == "bool":
            self.next()
            return _Bool(t.value)
        if t.kind == "ref":
            self.next()
            node = self._ref_atom(t.text)
            return node
        if t.kind == "ident":
            self.next()
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == "(":
                self.next()
                args = []
                if self.at_op(")"):
                    self.next()
                else:
                    args.append(self.arg())
                    while self.at_op(","):
                        self.next()
                        args.append(self.arg())
                    self.expect_op(")")
                return _Call(t.text.upper(), args)
            if _REF_RE.match(t.text):
                return _BadRef(t.text.upper())
            return _BadName(t.text)
        if t.kind == "op" and t.text == "(":
            self.next()
            node = self.parse()
            self.expect_op(")")
            return node
        raise _ParseSyntax()

    def _ref_atom(self, ref: str):
        row, col = parse_ref(ref)
        nxt = self.peek()
        if nxt is not None and nxt.kind == "op" and nxt.text == ":":
            self.next()
            t2 = self.next()
            if t2.kind != "ref":
                raise _ParseSyntax()
            row2, col2 = parse_ref(t2.text)
            return _Range((row, col), (row2, col2))
        return _Cell((row, col))

    def arg(self):
        # An argument may be a range.
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        if t.kind == "ref":
            save = self.i
            self.next()
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == ":":
                self.next()
                t2 = self.next()
                if t2.kind != "ref":
                    raise _ParseSyntax()
                row, col = parse_ref(t.text)
                row2, col2 = parse_ref(t2.text)
                return _Range((row, col), (row2, col2))
            self.i = save
        return self.parse()


def parse_formula(expr: str):
    toks = tokenize(expr)
    if not toks:
        raise _ParseSyntax()
    p = _Parser(toks)
    node = p.parse()
    if p.i != len(toks):
        raise _ParseSyntax()
    return node


# ---------------------------------------------------------------------------
# Numeric helpers
# ---------------------------------------------------------------------------

def _is_num(v) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _finite(v: float) -> float:
    if isinstance(v, bool) or not isinstance(v, (int, float)):
        return v
    f = float(v)
    if not math.isfinite(f):
        return VALUE_E
    return f


def _to_number(v, empty_as_zero: bool = True):
    """Arithmetic coercion. Returns a float or an error string."""
    if v is None:
        return 0.0 if empty_as_zero else None
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        return VALUE_E
    return VALUE_E


def _to_text(v) -> str:
    """Text coercion."""
    if v is None:
        return ""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, (int, float)):
        f = float(v)
        if math.isfinite(f) and f == int(f) and abs(f) < 1e15:
            return str(int(f))
        return repr(f)
    if isinstance(v, str):
        return v
    return str(v)


def _round_half_away(x: float, digits: int) -> float:
    if not math.isfinite(x):
        return VALUE_E
    d = Decimal(repr(x))
    with localcontext() as ctx:
        ctx.prec = 60
        q = Decimal(1).scaleb(-digits) if digits >= 0 else Decimal(1).scaleb(-digits)
        # scaleb(-digits) gives 10^-digits
        scaled = d / q
        # round half away from zero
        floor_scaled = scaled.to_integral_value(rounding="ROUND_FLOOR")
        ceil_scaled = scaled.to_integral_value(rounding="ROUND_CEILING")
        if scaled >= 0:
            choice = ceil_scaled if (scaled - floor_scaled) >= Decimal("0.5") else floor_scaled
            if (scaled - floor_scaled) == Decimal("0.5"):
                choice = ceil_scaled
        else:
            choice = floor_scaled if (ceil_scaled - scaled) >= Decimal("0.5") else ceil_scaled
            if (ceil_scaled - scaled) == Decimal("0.5"):
                choice = floor_scaled
        result = choice * q
    return float(result)


# ---------------------------------------------------------------------------
# Sheet
# ---------------------------------------------------------------------------

class Sheet:
    def __init__(self):
        self._raw: dict[tuple[int, int], str] = {}
        self._ast_cache: dict[tuple[int, int], object] = {}
        self._parse_fail: set[tuple[int, int]] = set()
        self._undo_stack: list[tuple[tuple[int, int], str | None]] = []
        self._values: dict[tuple[int, int], object] = {}
        self._dirty: set[tuple[int, int]] = set()
        self._direct_deps: dict[tuple[int, int], set[tuple[int, int]]] = {}
        self._direct_rdeps: dict[tuple[int, int], set[tuple[int, int]]] = {}

    # -- public API ---------------------------------------------------------

    def set(self, ref: str, raw: str) -> None:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")
        key = parse_ref(ref)
        old = self._raw.get(key)
        if raw == "":
            self._raw.pop(key, None)
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)
        else:
            self._raw[key] = raw
            self._parse_cell(key, raw)
        self._undo_stack.append((key, old))
        self._rebuild_graph()
        self._recompute_all()

    def get_raw(self, ref) -> str | None:
        key = parse_ref(ref)
        return self._raw.get(key)

    def get(self, ref):
        key = parse_ref(ref)
        if key not in self._raw:
            return None
        self._ensure_evaluated()
        return self._values.get(key)

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        key, old = self._undo_stack.pop()
        if old is None:
            self._raw.pop(key, None)
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)
        else:
            self._raw[key] = old
            self._parse_cell(key, old)
        self._rebuild_graph()
        self._recompute_all()
        return True

    def dependents(self, ref) -> list[str]:
        key = parse_ref(ref)
        self._ensure_graph()
        seen: set[tuple[int, int]] = set()
        stack = [key]
        while stack:
            cur = stack.pop()
            for dep in self._direct_rdeps.get(cur, ()):
                if dep not in seen:
                    seen.add(dep)
                    stack.append(dep)
        seen.discard(key)
        return [_ref_text(r, c) for (r, c) in sorted(seen)]

    def to_csv(self) -> str:
        if not self._raw:
            return ""
        max_row = max(r for (r, _) in self._raw)
        max_col = max(c for (_, c) in self._raw)
        lines = []
        for r in range(1, max_row + 1):
            fields = []
            for c in range(1, max_col + 1):
                v = self.get(_ref_text(r, c))
                fields.append(_csv_field(_to_text(v)))
            lines.append(",".join(fields))
        return "\n".join(lines)

    # -- internals ----------------------------------------------------------

    def _parse_cell(self, key: tuple[int, int], raw: str):
        if raw.startswith("="):
            try:
                self._ast_cache[key] = parse_formula(raw[1:])
                self._parse_fail.discard(key)
            except _ParseSyntax:
                self._ast_cache.pop(key, None)
                self._parse_fail.add(key)
        else:
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)

    def _ensure_graph(self):
        if not hasattr(self, "_graph_ok"):
            self._rebuild_graph()

    def _iter_formula_refs(self, key, ast):
        """Yield direct (cell/range) dependencies of an AST."""
        stack = [ast]
        while stack:
            node = stack.pop()
            if isinstance(node, _Cell):
                yield node.ref
            elif isinstance(node, _Range):
                yield (node.a, node.b)
            elif isinstance(node, _BadRef):
                pass
            elif isinstance(node, _Un):
                stack.append(node.x)
            elif isinstance(node, _Bin):
                stack.append(node.l)
                stack.append(node.r)
            elif isinstance(node, _Call):
                stack.extend(node.args)

    def _rebuild_graph(self):
        self._direct_deps = {}
        self._direct_rdeps = {}
        for key, ast in self._ast_cache.items():
            deps: set[tuple[int, int]] = set()
            stack = [ast]
            while stack:
                node = stack.pop()
                if isinstance(node, _Cell):
                    deps.add(node.ref)
                elif isinstance(node, _Range):
                    (r1, c1), (r2, c2) = node.a, node.b
                    r1, r2 = min(r1, r2), max(r1, r2)
                    c1, c2 = min(c1, c2), max(c1, c2)
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            deps.add((r, c))
                elif isinstance(node, _Un):
                    stack.append(node.x)
                elif isinstance(node, _Bin):
                    stack.append(node.l)
                    stack.append(node.r)
                elif isinstance(node, _Call):
                    stack.extend(node.args)
            deps.discard(key)
            self._direct_deps[key] = deps
            for d in deps:
                self._direct_rdeps.setdefault(d, set()).add(key)
        self._graph_ok = True

    def _find_cycle_members(self) -> set[tuple[int, int]]:
        """Cells that are part of a circular reference (through refs/ranges)."""
        # Build a dependency graph among formula cells only.
        formula_cells = set(self._ast_cache.keys())
        graph: dict[tuple[int, int], set[tuple[int, int]]] = {}
        for key in formula_cells:
            deps = set()
            for d in self._direct_deps.get(key, ()):
                if d in formula_cells:
                    deps.add(d)
            graph[key] = deps
        # Iterative Tarjan SCC.
        index_counter = [0]
        stack: list[tuple[int, int]] = []
        on_stack: set[tuple[int, int]] = set()
        index: dict[tuple[int, int], int] = {}
        lowlink: dict[tuple[int, int], int] = {}
        result: set[tuple[int, int]] = set()
        for start in graph:
            if start in index:
                continue
            work = [(start, iter(sorted(graph[start])))]
            index[start] = lowlink[start] = index_counter[0]
            index_counter[0] += 1
            stack.append(start)
            on_stack.add(start)
            while work:
                v, it = work[-1]
                advanced = False
                for w in it:
                    if w not in index:
                        index[w] = lowlink[w] = index_counter[0]
                        index_counter[0] += 1
                        stack.append(w)
                        on_stack.add(w)
                        work.append((w, iter(sorted(graph[w]))))
                        advanced = True
                        break
                    elif w in on_stack:
                        lowlink[v] = min(lowlink[v], index[w])
                if advanced:
                    continue
                work.pop()
                if work:
                    pv = work[-1][0]
                    lowlink[pv] = min(lowlink[pv], lowlink[v])
                if lowlink[v] == index[v]:
                    scc = []
                    while True:
                        w = stack.pop()
                        on_stack.discard(w)
                        scc.append(w)
                        if w == v:
                            break
                    if len(scc) > 1:
                        result.update(scc)
                    else:
                        w = scc[0]
                        if w in graph[w]:
                            result.add(w)
        return result

    def _recompute_all(self):
        cycle_members = self._find_cycle_members()
        values: dict[tuple[int, int], object] = {}
        # Topological order over formula cells (ignoring cycle edges).
        formula_cells = set(self._ast_cache.keys())
        state: dict[tuple[int, int], int] = {}
        order: list[tuple[int, int]] = []
        for start in sorted(formula_cells):
            if state.get(start):
                continue
            work = [(start, False)]
            while work:
                v, processed = work.pop()
                if processed:
                    order.append(v)
                    continue
                st = state.get(v, 0)
                if st == 2:
                    continue
                state[v] = 1
                work.append((v, True))
                for d in sorted(self._direct_deps.get(v, ())):
                    if d in formula_cells and state.get(d, 0) == 0:
                        work.append((d, False))
        for key in order:
            if key in cycle_members:
                values[key] = CYCLE_E
            else:
                values[key] = self._eval_ast(self._ast_cache[key], key, values, cycle_members)
        self._values = values
        self._cycle_members = cycle_members

    def _ensure_evaluated(self):
        if not hasattr(self, "_values") or self._values is None:
            self._recompute_all()

    def _cell_value(self, key, values, cycle_members):
        if key in cycle_members and key in self._ast_cache:
            return CYCLE_E
        if key in values:
            return values[key]
        if key in self._ast_cache:
            # Should be pre-computed in topological order; fall back.
            v = self._eval_ast(self._ast_cache[key], key, values, cycle_members)
            values[key] = v
            return v
        if key in self._parse_fail:
            return PARSE_E
        if key in self._raw:
            return self._literal_value(self._raw[key])
        return None

    def _literal_value(self, raw: str):
        s = raw.strip()
        if s == "":
            return raw
        try:
            f = float(s)
            if math.isfinite(f):
                return f
            return raw
        except ValueError:
            pass
        return raw

    # -- evaluation ---------------------------------------------------------

    def _eval_ast(self, ast, home, values, cycle_members):
        try:
            return self._ev(ast, home, values, cycle_members)
        except _RefOut as e:
            return REF_E
        except _EvalErr as e:
            return e.code

    def _ev(self, node, home, values, cycle_members):
        if isinstance(node, _Num):
            return node.v
        if isinstance(node, _Str):
            return node.v
        if isinstance(node, _Bool):
            return node.v
        if isinstance(node, _Cell):
            return self._cell_value(node.ref, values, cycle_members)
        if isinstance(node, _BadRef):
            return REF_E
        if isinstance(node, _BadName):
            return NAME_E
        if isinstance(node, _Range):
            return VALUE_E  # range outside a function argument
        if isinstance(node, _Un):
            v = self._ev(node.x, home, values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            r = -n if node.op == "-" else n
            return _finite(r)
        if isinstance(node, _Bin):
            return self._ev_bin(node, home, values, cycle_members)
        if isinstance(node, _Call):
            return self._ev_call(node, home, values, cycle_members)
        return VALUE_E

    def _ev_bin(self, node, home, values, cycle_members):
        op = node.op
        if op == "^":
            # right-associative; evaluate left then right
            l = self._ev(node.l, home, values, cycle_members)
            if isinstance(l, str) and l in ERROR_CODES:
                return l
            r = self._ev(node.r, home, values, cycle_members)
            if isinstance(r, str) and r in ERROR_CODES:
                return r
            ln = _to_number(l)
            if isinstance(ln, str):
