        if isinstance(l, str) and l in ERROR_CODES:
            return l
        r = self._ev(node.r, home, values, cycle_members)
        if isinstance(r, str) and r in ERROR_CODES:
            return r
        if op in ("=", "<>", "<", ">", "<=", ">="):
            return self._compare(op, l, r)
