            a, b = 0.0, float(r)
        elif ln and r is None:
            a, b = float(l), 0.0
        elif l is None and isinstance(r, bool):
            a, b = 0.0, (1.0 if r else 0.0)
        elif isinstance(l, bool) and r is None:
            a, b = (1.0 if l else 0.0), 0.0
