            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == ">":
            return a > b
        if op == "<=":
            return a <= b
        if op == ">=":
            return a >= b
        return VALUE_E

    def _range_values(self, rng: _Range, values, cycle_members):
        """Yield cell values in a range, row by row, left to right."""
        (r1, c1), (r2, c2) = rng.a, rng.b
        r1, r2 = min(r1, r2), max(r1, r2)
        c1, c2 = min(c1, c2), max(c1, c2)
