            if len(args) != 1:
                return VALUE_E
            v = self._ev(args[0], home, values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            return _finite(abs(n))
