class _Tok:
    __slots__ = ("kind", "text", "value")

    def __init__(self, kind, text, value=None):
        self.kind = kind
        self.text = text
        self.value = value


_NUMBER_RE = re.compile(r"[0-9]+(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?|\.[0-9]+(?:[eE][+-]?[0-9]+)?")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _is_ref_shape(word: str) -> bool:
    if not (2 <= len(word) <= 6):
        return False
    i = 0
    while i < len(word) and word[i].isalpha():
        i += 1
    if i == 0 or i > 2 or i == len(word):
        return False
    digits = word[i:]
    if not digits.isdigit():
        return False
    col = col_to_num(word[:i].upper())
    row = int(digits)
    return 1 <= row <= MAX_ROWS and 1 <= col <= MAX_COL


def tokenize(src: str):
    toks = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c in " \t\r\n\f\v":
            i += 1
            continue
        if c == '"':
            i += 1
            buf = []
            closed = False
            while i < n:
                if src[i] == '"':
                    if i + 1 < n and src[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                else:
                    buf.append(src[i])
                    i += 1
            if not closed:
                raise _ParseSyntax()
            toks.append(_Tok("string", "".join(buf)))
            continue
        if c.isdigit() or (c == "." and i + 1 < n and src[i + 1].isdigit()):
            m = _NUMBER_RE.match(src, i)
            toks.append(_Tok("number", m.group(0), float(m.group(0))))
            i = m.end()
            continue
        if c.isalpha() or c == "_":
            m = _IDENT_RE.match(src, i)
            word = m.group(0)
            i = m.end()
            up = word.upper()
            if up == "TRUE":
                toks.append(_Tok("bool", word, True))
            elif up == "FALSE":
                toks.append(_Tok("bool", word, False))
            elif _REF_RE.match(word):
                toks.append(_Tok("ref", word.upper()))
            else:
                toks.append(_Tok("ident", word))
            continue
        two = src[i:i + 2]
        if two in ("<>", "<=", ">="):
            toks.append(_Tok("op", two))
            i += 2
            continue
        if c in "=<>+-*/&^(),:":
            toks.append(_Tok("op", c))
            i += 1
            continue
        raise _ParseSyntax()
    return toks


