class _Parser:
    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def next(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        self.i += 1
        return t

    def at_op(self, *ops):
        t = self.peek()
        return t is not None and t.kind == "op" and t.text in ops

    def expect_op(self, op):
        t = self.peek()
        if t is None or t.kind != "op" or t.text != op:
            raise _ParseSyntax()
        self.i += 1

    def parse(self):
        node = self.concat()
        while self.at_op("=", "<>", "<", ">", "<=", ">="):
            op = self.next().text
            node = _Bin(op, node, self.concat())
        return node

    def concat(self):
        node = self.additive()
        while self.at_op("&"):
            self.next()
            node = _Bin("&", node, self.additive())
        return node

    def additive(self):
        node = self.multiplicative()
        while self.at_op("+", "-"):
            op = self.next().text
            node = _Bin(op, node, self.multiplicative())
        return node

    def multiplicative(self):
        node = self.unary()
        while self.at_op("*", "/"):
            op = self.next().text
            node = _Bin(op, node, self.unary())
        return node

    def unary(self):
        if self.at_op("-", "+"):
            op = self.next().text
            return _Un(op, self.unary())
        return self.power()

    def power(self):
        base = self.primary()
        if self.at_op("^"):
            self.next()
            return _Bin("^", base, self.unary())
        return base

    def primary(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        if t.kind == "number":
            self.next()
            return _Num(t.value)
        if t.kind == "string":
            self.next()
            return _Str(t.value)
        if t.kind == "bool":
            self.next()
            return _Bool(t.value)
        if t.kind == "ref":
            self.next()
            row, col = parse_ref(t.text)
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == ":":
                self.next()
                t2 = self.next()
                if t2.kind != "ref":
                    raise _ParseSyntax()
                row2, col2 = parse_ref(t2.text)
                return _Range((row, col), (row2, col2))
            return _Cell((row, col))
        if t.kind == "ident":
            self.next()
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == "(":
                self.next()
                args = []
                if self.at_op(")"):
                    self.next()
                else:
                    args.append(self.arg())
                    while self.at_op(","):
                        self.next()
                        args.append(self.arg())
                    self.expect_op(")")
                return _Call(t.text.upper(), args)
            if _REF_RE.match(t.text):
                return _BadRef(t.text.upper())
            return _BadName(t.text)
        if t.kind == "op" and t.text == "(":
            self.next()
            node = self.parse()
            self.expect_op(")")
            return node
        raise _ParseSyntax()

    def arg(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        if t.kind == "ref":
            save = self.i
            self.next()
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == ":":
                self.next()
                t2 = self.next()
                if t2.kind != "ref":
                    raise _ParseSyntax()
                row, col = parse_ref(t.text)
                row2, col2 = parse_ref(t2.text)
                return _Range((row, col), (row2, col2))
            self.i = save
        return self.parse()


def parse_formula(expr: str):
    toks = tokenize(expr)
    if not toks:
        raise _ParseSyntax()
    p = _Parser(toks)
    node = p.parse()
    if p.i != len(toks):
        raise _ParseSyntax()
    return node


def _is_num(v) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _finite(v):
    f = float(v)
    if not math.isfinite(f):
        return VALUE_E
    return f


def _to_number(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, (int, float)):
        return float(v)
    return VALUE_E


def _to_text(v) -> str:
    if v is None:
        return ""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, (int, float)):
        f = float(v)
        if math.isfinite(f) and f == int(f) and abs(f) < 1e15:
            return str(int(f))
        return repr(f)
    if isinstance(v, str):
        return v
    return str(v)


def _round_half_away(x: float, digits: int) -> float:
    if not math.isfinite(x):
        return VALUE_E
    d = Decimal(repr(x))
    q = Decimal(1).scaleb(-digits)
    with localcontext() as ctx:
        ctx.prec = 60
        scaled = d / q
        if scaled >= 0:
            fl = scaled.to_integral_value(rounding="ROUND_FLOOR")
            choice = fl + 1 if (scaled - fl) >= Decimal("0.5") else fl
        else:
            ce = scaled.to_integral_value(rounding="ROUND_CEILING")
            choice = ce - 1 if (ce - scaled) >= Decimal("0.5") else ce
        result = choice * q
    return float(result)


class Sheet:
    def __init__(self):
        self._raw = {}
        self._ast_cache = {}
        self._parse_fail = set()
        self._undo_stack = []
        self._values = {}
        self._direct_deps = {}
        self._direct_rdeps = {}
        self._computed = False

    def set(self, ref: str, raw: str) -> None:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")
        key = parse_ref(ref)
        old = self._raw.get(key)
        if raw == "":
            self._raw.pop(key, None)
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)
        else:
