                    self._parse_fail.discard(key)
                except _ParseSyntax:
                    self._ast_cache.pop(key, None)
                    self._parse_fail.add(key)
            else:
                self._ast_cache.pop(key, None)
                self._parse_fail.discard(key)
        self._undo_stack.append((key, old))
        self._rebuild_graph()
        self._recompute_all()

    def get_raw(self, ref) -> str | None:
        key = parse_ref(ref)
        return self._raw.get(key)

    def get(self, ref):
        key = parse_ref(ref)
        if key not in self._raw:
            return None
        if not self._computed:
            self._recompute_all()
        return self._values.get(key)

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        key, old = self._undo_stack.pop()
        if old is None:
            self._raw.pop(key, None)
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)
        else:
            self._raw[key] = old
            if old.startswith("="):
                try:
                    self._ast_cache[key] = parse_formula(old[1:])
                    self._parse_fail.discard(key)
                except _ParseSyntax:
                    self._ast_cache.pop(key, None)
                    self._parse_fail.add(key)
            else:
                self._ast_cache.pop(key, None)
                self._parse_fail.discard(key)
        self._rebuild_graph()
        self._recompute_all()
        return True

    def dependents(self, ref) -> list[str]:
        key = parse_ref(ref)
        seen = set()
        stack = [key]
        while stack:
            cur = stack.pop()
            for dep in self._direct_rdeps.get(cur, ()):
                if dep not in seen:
                    seen.add(dep)
                    stack.append(dep)
