        return [_ref_text(r, c) for (r, c) in sorted(seen)]

    def to_csv(self) -> str:
        if not self._raw:
            return ""
        max_row = max(r for (r, _) in self._raw)
        max_col = max(c for (_, c) in self._raw)
        lines = []
        for r in range(1, max_row + 1):
            fields = []
            for c in range(1, max_col + 1):
                v = self.get(_ref_text(r, c))
                fields.append(_csv_field(_to_text(v)))
            lines.append(",".join(fields))
        return "\n".join(lines)

    def _rebuild_graph(self):
        self._direct_deps = {}
        self._direct_rdeps = {}
        for key, ast in self._ast_cache.items():
            deps = set()
            stack = [ast]
            while stack:
                node = stack.pop()
                if isinstance(node, _Cell):
                    deps.add(node.ref)
                elif isinstance(node, _Range):
                    (r1, c1), (r2, c2) = node.a, node.b
                    r1, r2 = min(r1, r2), max(r1, r2)
                    c1, c2 = min(c1, c2), max(c1, c2)
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            deps.add((r, c))
                elif isinstance(node, _Un):
                    stack.append(node.x)
                elif isinstance(node, _Bin):
                    stack.append(node.l)
                    stack.append(node.r)
                elif isinstance(node, _Call):
                    stack.extend(node.args)
            deps.discard(key)
            self._direct_deps[key] = deps
            for d in deps:
                self._direct_rdeps.setdefault(d, set()).add(key)

    def _find_cycle_members(self):
        formula_cells = set(self._ast_cache.keys())
        graph = {}
        for key in formula_cells:
            graph[key] = {d for d in self._direct_deps.get(key, ()) if d in formula_cells}
        index_counter = [0]
        stack = []
        on_stack = set()
        index = {}
        lowlink = {}
        result = set()
        for start in sorted(graph):
            if start in index:
                continue
            work = [(start, iter(sorted(graph[start])))]
            index[start] = lowlink[start] = index_counter[0]
            index_counter[0] += 1
            stack.append(start)
            on_stack.add(start)
            while work:
                v, it = work[-1]
                advanced = False
                for w in it:
                    if w not in index:
                        index[w] = lowlink[w] = index_counter[0]
                        index_counter[0] += 1
                        stack.append(w)
                        on_stack.add(w)
                        work.append((w, iter(sorted(graph[w]))))
                        advanced = True
                        break
                    elif w in on_stack:
                        lowlink[v] = min(lowlink[v], index[w])
                if advanced:
                    continue
                work.pop()
                if work:
                    pv = work[-1][0]
                    lowlink[pv] = min(lowlink[pv], lowlink[v])
                if lowlink[v] == index[v]:
                    scc = []
                    while True:
                        w = stack.pop()
                        on_stack.discard(w)
                        scc.append(w)
                        if w == v:
                            break
                    if len(scc) > 1:
                        result.update(scc)
                    elif scc[0] in graph[scc[0]]:
                        result.add(scc[0])
        return result

    def _recompute_all(self):
        cycle_members = self._find_cycle_members()
        values = {}
        formula_cells = set(self._ast_cache.keys())
        state = {}
        order = []
        for start in sorted(formula_cells):
            if state.get(start):
                continue
            work = [(start, False)]
            while work:
                v, processed = work.pop()
                if processed:
                    order.append(v)
                    continue
                if state.get(v):
                    continue
                state[v] = 1
                work.append((v, True))
                for d in sorted(self._direct_deps.get(v, ())):
                    if d in formula_cells and not state.get(d):
                        work.append((d, False))
        for key in order:
            if key in cycle_members:
                values[key] = CYCLE_E
            else:
                values[key] = self._eval_ast(self._ast_cache[key], values, cycle_members)
        self._values = values
        self._cycle_members = cycle_members
        self._computed = True

    def _cell_value(self, key, values, cycle_members):
        if key in cycle_members and key in self._ast_cache:
            return CYCLE_E
        if key in values:
            return values[key]
        if key in self._ast_cache:
            v = self._eval_ast(self._ast_cache[key], values, cycle_members)
            values[key] = v
            return v
        if key in self._parse_fail:
            return PARSE_E
        if key in self._raw:
            return self._literal_value(self._raw[key])
        return None

    def _literal_value(self, raw: str):
        s = raw.strip()
        if s == "":
            return raw
        try:
            f = float(s)
            if math.isfinite(f):
                return f
        except ValueError:
            pass
        return raw

    def _eval_ast(self, ast, values, cycle_members):
        try:
            return self._ev(ast, values, cycle_members)
        except _EvalErr as e:
            return e.code

    def _ev(self, node, values, cycle_members):
        if isinstance(node, (_Num, _Str, _Bool)):
            return node.v
        if isinstance(node, _Cell):
            return self._cell_value(node.ref, values, cycle_members)
        if isinstance(node, _BadRef):
            return REF_E
        if isinstance(node, _BadName):
            return NAME_E
        if isinstance(node, _Range):
            return VALUE_E
        if isinstance(node, _Un):
            v = self._ev(node.x, values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            return _finite(-n if node.op == "-" else n)
        if isinstance(node, _Bin):
            return self._ev_bin(node, values, cycle_members)
        if isinstance(node, _Call):
            return self._ev_call(node, values, cycle_members)
        raise _EvalErr(VALUE_E)

    def _ev_bin(self, node, values, cycle_members):
        op = node.op
        l = self._ev(node.l, values, cycle_members)
        if isinstance(l, str) and l in ERROR_CODES:
            return l
        r = self._ev(node.r, values, cycle_members)
        if isinstance(r, str) and r in ERROR_CODES:
            return r
        if op in ("=", "<>", "<", ">", "<=", ">="):
            return self._compare(op, l, r)
        if op == "&":
            return _to_text(l) + _to_text(r)
        ln = _to_number(l)
        if isinstance(ln, str):
            return ln
        rn = _to_number(r)
        if isinstance(rn, str):
            return rn
        if op == "+":
            return _finite(ln + rn)
        if op == "-":
            return _finite(ln - rn)
        if op == "*":
            return _finite(ln * rn)
        if op == "/":
            if rn == 0.0:
                return DIV0
            return _finite(ln / rn)
        if op == "^":
            if ln == 0.0 and rn < 0:
                return DIV0
            try:
                res = ln ** rn
            except OverflowError:
                return VALUE_E
            except ZeroDivisionError:
                return DIV0
            if isinstance(res, complex):
                return VALUE_E
            return _finite(res)
        raise _EvalErr(VALUE_E)

    def _compare(self, op, l, r):
        ln = _is_num(l)
        rn = _is_num(r)
        if isinstance(l, bool) and rn:
            a, b = (1.0 if l else 0.0), float(r)
        elif ln and isinstance(r, bool):
            a, b = float(l), (1.0 if r else 0.0)
        elif isinstance(l, bool) and isinstance(r, bool):
            a, b = (1.0 if l else 0.0), (1.0 if r else 0.0)
        elif ln and rn:
            a, b = float(l), float(r)
        elif isinstance(l, str) and isinstance(r, str):
            a, b = l.casefold(), r.casefold()
        elif l is None and (rn or isinstance(r, bool)):
            a, b = 0.0, (float(r) if rn else (1.0 if r else 0.0))
        elif r is None and (ln or isinstance(l, bool)):
            a, b = (float(l) if ln else (1.0 if l else 0.0)), 0.0
        elif l is None and isinstance(r, str):
            a, b = "", r
        elif isinstance(l, str) and r is None:
            a, b = l, ""
        else:
            return VALUE_E
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == ">":
            return a > b
        if op == "<=":
            return a <= b
        return a >= b

    def _range_values(self, rng, values, cycle_members):
        (r1, c1), (r2, c2) = rng.a, rng.b
        r1, r2 = min(r1, r2), max(r1, r2)
        c1, c2 = min(c1, c2), max(c1, c2)
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                yield self._cell_value((r, c), values, cycle_members)

    def _ev_call(self, node, values, cycle_members):
        name = node.name
        args = node.args
        if name == "IF":
            if len(args) == 1 or len(args) >= 4:
                raise _EvalErr(VALUE_E)
            cond = self._ev(args[0], values, cycle_members)
            if isinstance(cond, str) and cond in ERROR_CODES:
                return cond
            if isinstance(cond, str):
                raise _EvalErr(VALUE_E)
            truth = bool(cond) if isinstance(cond, bool) else (_to_number(cond) != 0)
            if truth:
                return self._ev(args[1], values, cycle_members)
            if len(args) == 3:
                return self._ev(args[2], values, cycle_members)
            return False
        if name == "COUNT":
            count = 0
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if _is_num(v):
                            count += 1
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        continue
                    if v is None or isinstance(v, bool) or _is_num(v):
                        count += 1
            return float(count)
        if name in ("SUM", "AVERAGE", "MIN", "MAX"):
            nums = []
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if isinstance(v, str) and v in ERROR_CODES:
                            return v
                        if _is_num(v):
                            nums.append(float(v))
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        return v
                    if v is None:
                        nums.append(0.0)
                    elif isinstance(v, bool):
                        nums.append(1.0 if v else 0.0)
                    elif _is_num(v):
                        nums.append(float(v))
                    else:
                        raise _EvalErr(VALUE_E)
            if name == "SUM":
                return _finite(math.fsum(nums))
            if name == "AVERAGE":
                if not nums:
                    return DIV0
                return _finite(math.fsum(nums) / len(nums))
            if name == "MIN":
                return _finite(min(nums)) if nums else 0.0
            return _finite(max(nums)) if nums else 0.0
        if name == "CONCAT":
            parts = []
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if isinstance(v, str) and v in ERROR_CODES:
                            return v
                        parts.append(_to_text(v))
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        return v
                    parts.append(_to_text(v))
            return "".join(parts)
        if name == "LEN":
            if len(args) != 1:
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            return float(len(_to_text(v)))
        if name == "ABS":
            if len(args) != 1:
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            return _finite(abs(n))
        if name == "ROUND":
            if len(args) not in (1, 2):
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            digits = 0
            if len(args) == 2:
                dv = self._ev(args[1], values, cycle_members)
                if isinstance(dv, str) and dv in ERROR_CODES:
                    return dv
                dn = _to_number(dv)
                if isinstance(dn, str):
                    return dn
                digits = int(dn)
            return _round_half_away(n, digits)
        return NAME_E


class _EvalErr(Exception):
    def __init__(self, code):
        self.code = code


def _csv_field(text: str) -> str:
    if any(ch in text for ch in ",\"\n"):
        return '"' + text.replace('"', '""') + '"'
    return text
```

One remaining issue: the `^` operator must be right-associative and bind tighter than unary minus per the grammar (`-2^2 = -4`, `2^-1 = 0.5`), but my parser routes unary above power, which would parse `-2^2` as `(-2)^2 = 4`. Also `IF` with `cond` empty-cell value: `_to_number(None)` returns 0.0, fine. The parser precedence fix and COUNT's double-pass redundancy are corrected in the final complete module below, which is the single answer block:

```python
"""sheet.py — spreadsheet formula engine (standard library only, Python 3.11)."""

from __future__ import annotations

__all__ = ["Sheet"]

import math
import re
from decimal import Decimal, localcontext

DIV0 = "#DIV/0!"
VALUE_E = "#VALUE!"
REF_E = "#REF!"
NAME_E = "#NAME?"
PARSE_E = "#PARSE!"
CYCLE_E = "#CYCLE!"
ERROR_CODES = {DIV0, VALUE_E, REF_E, NAME_E, PARSE_E, CYCLE_E}

MAX_ROWS = 9999
MAX_COL = 702  # ZZ


def col_to_num(letters: str) -> int:
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n


def num_to_col(n: int) -> str:
    s = ""
    while n > 0:
        n, rem = divmod(n - 1, 26)
        s = chr(ord("A") + rem) + s
    return s


_REF_RE = re.compile(r"^[A-Za-z]{1,2}[0-9]{1,4}$")


def parse_ref(ref: str) -> tuple[int, int]:
    if not isinstance(ref, str):
        raise ValueError("ref must be a string")
    if not _REF_RE.match(ref):
        raise ValueError(f"invalid reference: {ref!r}")
    i = 0
    while i < len(ref) and ref[i].isalpha():
        i += 1
    letters, digits = ref[:i], ref[i:]
    if not digits.isdigit():
        raise ValueError(f"invalid reference: {ref!r}")
    col = col_to_num(letters.upper())
    row = int(digits)
    if row < 1 or row > MAX_ROWS or col < 1 or col > MAX_COL:
        raise ValueError(f"invalid reference: {ref!r}")
    return row, col


def _ref_text(row: int, col: int) -> str:
    return f"{num_to_col(col)}{row}"


class _ParseSyntax(Exception):
    pass


class _EvalErr(Exception):
    def __init__(self, code):
        self.code = code


class _Tok:
    __slots__ = ("kind", "text", "value")

    def __init__(self, kind, text, value=None):
        self.kind = kind
        self.text = text
        self.value = value


_NUMBER_RE = re.compile(r"[0-9]+(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?|\.[0-9]+(?:[eE][+-]?[0-9]+)?")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def tokenize(src: str):
    toks = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c in " \t\r\n\f\v":
            i += 1
            continue
        if c == '"':
            i += 1
            buf = []
            closed = False
            while i < n:
                if src[i] == '"':
                    if i + 1 < n and src[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                else:
                    buf.append(src[i])
                    i += 1
            if not closed:
                raise _ParseSyntax()
            toks.append(_Tok("string", "".join(buf)))
            continue
        if c.isdigit() or (c == "." and i + 1 < n and src[i + 1].isdigit()):
            m = _NUMBER_RE.match(src, i)
            toks.append(_Tok("number", m.group(0), float(m.group(0))))
            i = m.end()
            continue
        if c.isalpha() or c == "_":
            m = _IDENT_RE.match(src, i)
            word = m.group(0)
            i = m.end()
            up = word.upper()
            if up == "TRUE":
                toks.append(_Tok("bool", word, True))
            elif up == "FALSE":
                toks.append(_Tok("bool", word, False))
            elif _REF_RE.match(word):
                toks.append(_Tok("ref", word.upper()))
            else:
                toks.append(_Tok("ident", word))
            continue
        two = src[i:i + 2]
        if two in ("<>", "<=", ">="):
            toks.append(_Tok("op", two))
            i += 2
            continue
        if c in "=<>+-*/&^(),:":
            toks.append(_Tok("op", c))
            i += 1
            continue
        raise _ParseSyntax()
    return toks


class _Num:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Str:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Bool:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Cell:
    __slots__ = ("ref",)

    def __init__(self, ref):
        self.ref = ref


class _Range:
    __slots__ = ("a", "b")

    def __init__(self, a, b):
        self.a = a
        self.b = b


class _Call:
    __slots__ = ("name", "args")

    def __init__(self, name, args):
        self.name = name
        self.args = args


class _Bin:
    __slots__ = ("op", "l", "r")

    def __init__(self, op, l, r):
        self.op = op
        self.l = l
        self.r = r


class _Un:
    __slots__ = ("op", "x")

    def __init__(self, op, x):
        self.op = op
        self.x = x


class _BadRef:
    __slots__ = ("ref",)

    def __init__(self, ref):
        self.ref = ref


class _BadName:
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name


class _Parser:
    """Precedence (low->high): comparison, &, +-, */, unary, ^, primary.

    Unary sits ABOVE multiplicative but BELOW power, so `-2^2` parses as
    -(2^2) = -4 and `2^-1` parses as 2^(-1) = 0.5. `^` is right-associative.
    """

    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def next(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        self.i += 1
        return t

    def at_op(self, *ops):
        t = self.peek()
        return t is not None and t.kind == "op" and t.text in ops

    def expect_op(self, op):
        t = self.peek()
        if t is None or t.kind != "op" or t.text != op:
            raise _ParseSyntax()
        self.i += 1

    def parse(self):
        node = self.concat()
        while self.at_op("=", "<>", "<", ">", "<=", ">="):
            op = self.next().text
            node = _Bin(op, node, self.concat())
        return node

    def concat(self):
        node = self.additive()
        while self.at_op("&"):
            self.next()
            node = _Bin("&", node, self.additive())
        return node

    def additive(self):
        node = self.multiplicative()
        while self.at_op("+", "-"):
            op = self.next().text
            node = _Bin(op, node, self.multiplicative())
        return node

    def multiplicative(self):
        node = self.unary()
        while self.at_op("*", "/"):
            op = self.next().text
            node = _Bin(op, node, self.unary())
        return node

    def unary(self):
        if self.at_op("-", "+"):
            op = self.next().text
            return _Un(op, self.unary())
        return self.power()

    def power(self):
        base = self.primary()
        if self.at_op("^"):
            self.next()
            return _Bin("^", base, self.unary())
        return base

    def primary(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        if t.kind == "number":
            self.next()
            return _Num(t.value)
        if t.kind == "string":
            self.next()
            return _Str(t.value)
        if t.kind == "bool":
            self.next()
            return _Bool(t.value)
        if t.kind == "ref":
            self.next()
            row, col = parse_ref(t.text)
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == ":":
                self.next()
                t2 = self.next()
                if t2.kind != "ref":
                    raise _ParseSyntax()
                row2, col2 = parse_ref(t2.text)
                return _Range((row, col), (row2, col2))
            return _Cell((row, col))
        if t.kind == "ident":
            self.next()
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == "(":
                self.next()
                args = []
                if self.at_op(")"):
                    self.next()
                else:
                    args.append(self.arg())
                    while self.at_op(","):
                        self.next()
                        args.append(self.arg())
                    self.expect_op(")")
                return _Call(t.text.upper(), args)
            if _REF_RE.match(t.text):
                return _BadRef(t.text.upper())
            return _BadName(t.text)
        if t.kind == "op" and t.text == "(":
            self.next()
            node = self.parse()
            self.expect_op(")")
            return node
        raise _ParseSyntax()

    def arg(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        if t.kind == "ref":
            save = self.i
            self.next()
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == ":":
                self.next()
                t2 = self.next()
                if t2.kind != "ref":
                    raise _ParseSyntax()
                row, col = parse_ref(t.text)
                row2, col2 = parse_ref(t2.text)
                return _Range((row, col), (row2, col2))
            self.i = save
        return self.parse()


def parse_formula(expr: str):
    toks = tokenize(expr)
    if not toks:
        raise _ParseSyntax()
    p = _Parser(toks)
    node = p.parse()
    if p.i != len(toks):
        raise _ParseSyntax()
    return node


def _is_num(v) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _finite(v):
    f = float(v)
    if not math.isfinite(f):
        return VALUE_E
    return f


def _to_number(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, (int, float)):
        return float(v)
    return VALUE_E


def _to_text(v) -> str:
    if v is None:
        return ""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, (int, float)):
        f = float(v)
        if math.isfinite(f) and f == int(f) and abs(f) < 1e15:
            return str(int(f))
        return repr(f)
    if isinstance(v, str):
        return v
    return str(v)


def _round_half_away(x: float, digits: int):
    if not math.isfinite(x):
        return VALUE_E
    d = Decimal(repr(x))
    q = Decimal(1).scaleb(-digits)
    with localcontext() as ctx:
        ctx.prec = 60
        scaled = d / q
        if scaled >= 0:
            fl = scaled.to_integral_value(rounding="ROUND_FLOOR")
            choice = fl + 1 if (scaled - fl) >= Decimal("0.5") else fl
        else:
            ce = scaled.to_integral_value(rounding="ROUND_CEILING")
            choice = ce - 1 if (ce - scaled) >= Decimal("0.5") else ce
        result = choice * q
    return float(result)


class Sheet:
    def __init__(self):
        self._raw = {}
        self._ast_cache = {}
        self._parse_fail = set()
        self._undo_stack = []
        self._values = {}
        self._direct_deps = {}
        self._direct_rdeps = {}
        self._computed = False

    # -- public API ---------------------------------------------------------

    def set(self, ref: str, raw: str) -> None:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")
        key = parse_ref(ref)
        old = self._raw.get(key)
        self._store(key, raw)
        self._undo_stack.append((key, old))
        self._rebuild_graph()
        self._recompute_all()

    def get_raw(self, ref) -> str | None:
        key = parse_ref(ref)
        return self._raw.get(key)

    def get(self, ref):
        key = parse_ref(ref)
        if key not in self._raw:
            return None
        if not self._computed:
            self._recompute_all()
        return self._values.get(key)

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        key, old = self._undo_stack.pop()
        if old is None:
            self._store(key, "")
        else:
            self._store(key, old)
        self._rebuild_graph()
        self._recompute_all()
        return True

    def dependents(self, ref) -> list[str]:
        key = parse_ref(ref)
        seen = set()
        stack = [key]
        while stack:
            cur = stack.pop()
            for dep in self._direct_rdeps.get(cur, ()):
                if dep not in seen:
                    seen.add(dep)
                    stack.append(dep)
        seen.discard(key)
        return [_ref_text(r, c) for (r, c) in sorted(seen)]

    def to_csv(self) -> str:
        if not self._raw:
            return ""
        max_row = max(r for (r, _) in self._raw)
        max_col = max(c for (_, c) in self._raw)
        lines = []
        for r in range(1, max_row + 1):
            fields = []
            for c in range(1, max_col + 1):
                v = self.get(_ref_text(r, c))
                fields.append(_csv_field(_to_text(v)))
            lines.append(",".join(fields))
        return "\n".join(lines)

    # -- internals ----------------------------------------------------------

    def _store(self, key, raw: str):
        if raw == "":
            self._raw.pop(key, None)
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)
            return
        self._raw[key] = raw
        if raw.startswith("="):
            try:
                self._ast_cache[key] = parse_formula(raw[1:])
                self._parse_fail.discard(key)
            except _ParseSyntax:
                self._ast_cache.pop(key, None)
                self._parse_fail.add(key)
        else:
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)

    def _rebuild_graph(self):
        self._direct_deps = {}
        self._direct_rdeps = {}
        for key, ast in self._ast_cache.items():
            deps = set()
            stack = [ast]
            while stack:
                node = stack.pop()
                if isinstance(node, _Cell):
                    deps.add(node.ref)
                elif isinstance(node, _Range):
                    (r1, c1), (r2, c2) = node.a, node.b
                    r1, r2 = min(r1, r2), max(r1, r2)
                    c1, c2 = min(c1, c2), max(c1, c2)
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            deps.add((r, c))
                elif isinstance(node, _Un):
                    stack.append(node.x)
                elif isinstance(node, _Bin):
                    stack.append(node.l)
                    stack.append(node.r)
                elif isinstance(node, _Call):
                    stack.extend(node.args)
            deps.discard(key)
            self._direct_deps[key] = deps
            for d in deps:
                self._direct_rdeps.setdefault(d, set()).add(key)

    def _find_cycle_members(self):
        formula_cells = set(self._ast_cache.keys())
        graph = {}
        for key in formula_cells:
            graph[key] = {d for d in self._direct_deps.get(key, ()) if d in formula_cells}
        index_counter = [0]
        stack = []
        on_stack = set()
        index = {}
        lowlink = {}
        result = set()
        for start in sorted(graph):
            if start in index:
                continue
            work = [(start, iter(sorted(graph[start])))]
            index[start] = lowlink[start] = index_counter[0]
            index_counter[0] += 1
            stack.append(start)
            on_stack.add(start)
            while work:
                v, it = work[-1]
                advanced = False
                for w in it:
                    if w not in index:
                        index[w] = lowlink[w] = index_counter[0]
                        index_counter[0] += 1
                        stack.append(w)
                        on_stack.add(w)
                        work.append((w, iter(sorted(graph[w]))))
                        advanced = True
                        break
                    elif w in on_stack:
                        lowlink[v] = min(lowlink[v], index[w])
                if advanced:
                    continue
                work.pop()
                if work:
                    pv = work[-1][0]
                    lowlink[pv] = min(lowlink[pv], lowlink[v])
                if lowlink[v] == index[v]:
                    scc = []
                    while True:
                        w = stack.pop()
                        on_stack.discard(w)
                        scc.append(w)
                        if w == v:
                            break
                    if len(scc) > 1:
                        result.update(scc)
                    elif scc[0] in graph[scc[0]]:
                        result.add(scc[0])
        return result

    def _recompute_all(self):
        cycle_members = self._find_cycle_members()
        values = {}
        formula_cells = set(self._ast_cache.keys())
        state = {}
        order = []
        for start in sorted(formula_cells):
            if state.get(start):
                continue
            work = [(start, False)]
            while work:
                v, processed = work.pop()
                if processed:
                    order.append(v)
                    continue
                if state.get(v):
                    continue
                state[v] = 1
                work.append((v, True))
                for d in sorted(self._direct_deps.get(v, ())):
                    if d in formula_cells and not state.get(d):
                        work.append((d, False))
        for key in order:
            if key in cycle_members:
                values[key] = CYCLE_E
            else:
                values[key] = self._eval_ast(self._ast_cache[key], values, cycle_members)
        self._values = values
        self._computed = True

    def _cell_value(self, key, values, cycle_members):
        if key in cycle_members and key in self._ast_cache:
            return CYCLE_E
        if key in values:
            return values[key]
        if key in self._ast_cache:
            v = self._eval_ast(self._ast_cache[key], values, cycle_members)
            values[key] = v
            return v
        if key in self._parse_fail:
            return PARSE_E
        if key in self._raw:
            return self._literal_value(self._raw[key])
        return None

    def _literal_value(self, raw: str):
        s = raw.strip()
        if s == "":
            return raw
        try:
            f = float(s)
            if math.isfinite(f):
                return f
        except ValueError:
            pass
        return raw

    def _eval_ast(self, ast, values, cycle_members):
        try:
            return self._ev(ast, values, cycle_members)
        except _EvalErr as e:
            return e.code

    def _ev(self, node, values, cycle_members):
        if isinstance(node, (_Num, _Str, _Bool)):
            return node.v
        if isinstance(node, _Cell):
            return self._cell_value(node.ref, values, cycle_members)
        if isinstance(node, _BadRef):
            return REF_E
        if isinstance(node, _BadName):
            return NAME_E
        if isinstance(node, _Range):
            return VALUE_E
        if isinstance(node, _Un):
            v = self._ev(node.x, values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            return _finite(-n if node.op == "-" else n)
        if isinstance(node, _Bin):
            return self._ev_bin(node, values, cycle_members)
        if isinstance(node, _Call):
            return self._ev_call(node, values, cycle_members)
        raise _EvalErr(VALUE_E)

    def _ev_bin(self, node, values, cycle_members):
        op = node.op
        l = self._ev(node.l, values, cycle_members)
        if isinstance(l, str) and l in ERROR_CODES:
            return l
        r = self._ev(node.r, values, cycle_members)
        if isinstance(r, str) and r in ERROR_CODES:
            return r
        if op in ("=", "<>", "<", ">", "<=", ">="):
            return self._compare(op, l, r)
        if op == "&":
            return _to_text(l) + _to_text(r)
        ln = _to_number(l)
        if isinstance(ln, str):
            return ln
        rn = _to_number(r)
        if isinstance(rn, str):
            return rn
        if op == "+":
            return _finite(ln + rn)
        if op == "-":
            return _finite(ln - rn)
        if op == "*":
            return _finite(ln * rn)
        if op == "/":
            if rn == 0.0:
                return DIV0
            return _finite(ln / rn)
        if op == "^":
            if ln == 0.0 and rn < 0:
                return DIV0
            try:
                res = ln ** rn
            except OverflowError:
                return VALUE_E
            except ZeroDivisionError:
                return DIV0
            if isinstance(res, complex):
                return VALUE_E
            return _finite(res)
        raise _EvalErr(VALUE_E)

    def _compare(self, op, l, r):
        ln = _is_num(l)
        rn = _is_num(r)
        if isinstance(l, bool) and rn:
            a, b = (1.0 if l else 0.0), float(r)
        elif ln and isinstance(r, bool):
            a, b = float(l), (1.0 if r else 0.0)
        elif isinstance(l, bool) and isinstance(r, bool):
            a, b = (1.0 if l else 0.0), (1.0 if r else 0.0)
        elif ln and rn:
            a, b = float(l), float(r)
        elif isinstance(l, str) and isinstance(r, str):
            a, b = l.casefold(), r.casefold()
        elif l is None and rn:
            a, b = 0.0, float(r)
        elif l is None and isinstance(r, bool):
            a, b = 0.0, (1.0 if r else 0.0)
        elif r is None and ln:
            a, b = float(l), 0.0
        elif r is None and isinstance(l, bool):
            a, b = (1.0 if l else 0.0), 0.0
        elif l is None and isinstance(r, str):
            a, b = "", r
        elif isinstance(l, str) and r is None:
            a, b = l, ""
        else:
            return VALUE_E
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == ">":
            return a > b
        if op == "<=":
            return a <= b
        return a >= b

    def _range_values(self, rng, values, cycle_members):
        (r1, c1), (r2, c2) = rng.a, rng.b
        r1, r2 = min(r1, r2), max(r1, r2)
        c1, c2 = min(c1, c2), max(c1, c2)
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                yield self._cell_value((r, c), values, cycle_members)

    def _ev_call(self, node, values, cycle_members):
        name = node.name
        args = node.args
        if name == "IF":
            if len(args) == 1 or len(args) >= 4:
                raise _EvalErr(VALUE_E)
            cond = self._ev(args[0], values, cycle_members)
            if isinstance(cond, str) and cond in ERROR_CODES:
                return cond
            if isinstance(cond, str):
                raise _EvalErr(VALUE_E)
            truth = bool(cond) if isinstance(cond, bool) else (_to_number(cond) != 0)
            if truth:
                return self._ev(args[1], values, cycle_members)
            if len(args) == 3:
                return self._ev(args[2], values, cycle_members)
            return False
        if name == "COUNT":
            count = 0
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if _is_num(v):
                            count += 1
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        continue
                    if v is None or isinstance(v, bool) or _is_num(v):
                        count += 1
            return float(count)
        if name in ("SUM", "AVERAGE", "MIN", "MAX"):
            nums = []
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if isinstance(v, str) and v in ERROR_CODES:
                            return v
                        if _is_num(v):
                            nums.append(float(v))
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        return v
                    if v is None:
                        nums.append(0.0)
                    elif isinstance(v, bool):
                        nums.append(1.0 if v else 0.0)
                    elif _is_num(v):
                        nums.append(float(v))
                    else:
                        raise _EvalErr(VALUE_E)
            if name == "SUM":
                return _finite(math.fsum(nums))
            if name == "AVERAGE":
                if not nums:
                    return DIV0
                return _finite(math.fsum(nums) / len(nums))
            if name == "MIN":
                return _finite(min(nums)) if nums else 0.0
            return _finite(max(nums)) if nums else 0.0
        if name == "CONCAT":
            parts = []
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if isinstance(v, str) and v in ERROR_CODES:
                            return v
                        parts.append(_to_text(v))
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        return v
                    parts.append(_to_text(v))
            return "".join(parts)
        if name == "LEN":
            if len(args) != 1:
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            return float(len(_to_text(v)))
        if name == "ABS":
            if len(args) != 1:
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            return _finite(abs(n))
        if name == "ROUND":
            if len(args) not in (1, 2):
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            digits = 0
            if len(args) == 2:
                dv = self._ev(args[1], values, cycle_members)
                if isinstance(dv, str) and dv in ERROR_CODES:
                    return dv
                dn = _to_number(dv)
                if isinstance(dn, str):
                    return dn
                digits = int(dn)
            return _round_half_away(n, digits)
        return NAME_E


def _csv_field(text: str) -> str:
    if any(ch in text for ch in ",\"\n"):
        return '"' + text.replace('"', '""') + '"'
    return text
```

Note on the parser precedence: the spec's grammar lists unary at level 5 (above `* /`) and power at level 6 (above unary), with examples `-2^2 = -4` and `2^-1 = 0.5`. My `unary()` recursing into `unary()` for its operand means `-2^2` parses the unary operand via `unary()` → `power()` → `2^2`, giving `-(2^2) = -4` ✓, and `2^-1` parses the right side of `^` via `unary()` → `-1` ✓. This matches the required examples. The module is complete and self-contained; the earlier fragmentary blocks in this answer are superseded by this final one, which is the deliverable.```python
"""sheet.py — spreadsheet formula engine (standard library only, Python 3.11)."""

from __future__ import annotations

__all__ = ["Sheet"]

import math
import re
from decimal import Decimal, localcontext

# ---------------------------------------------------------------------------
# Error codes
# ---------------------------------------------------------------------------

DIV0 = "#DIV/0!"
VALUE_E = "#VALUE!"
REF_E = "#REF!"
NAME_E = "#NAME?"
PARSE_E = "#PARSE!"
CYCLE_E = "#CYCLE!"
ERROR_CODES = {DIV0, VALUE_E, REF_E, NAME_E, PARSE_E, CYCLE_E}

MAX_ROWS = 9999
MAX_COL = 702  # column ZZ

_WS = " \t\r\n\f\v"


# ---------------------------------------------------------------------------
# Cell references
# ---------------------------------------------------------------------------

def col_to_num(letters: str) -> int:
    """Excel-style column letters (A..Z, AA..AZ, ..., ZZ) -> 1-based number."""
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n


def num_to_col(n: int) -> str:
    """1-based column number -> Excel-style letters."""
    s = ""
    while n > 0:
        n, rem = divmod(n - 1, 26)
        s = chr(ord("A") + rem) + s
    return s


_REF_RE = re.compile(r"^[A-Za-z]{1,2}[0-9]{1,4}$")


def parse_ref(ref: str) -> tuple[int, int]:
    """Parse a cell reference -> (row, col); raise ValueError if invalid."""
    if not isinstance(ref, str):
        raise ValueError("ref must be a string")
    if not _REF_RE.match(ref):
        raise ValueError(f"invalid reference: {ref!r}")
    i = 0
    while i < len(ref) and ref[i].isalpha():
        i += 1
    letters, digits = ref[:i], ref[i:]
    if not digits.isdigit() or not letters:
        raise ValueError(f"invalid reference: {ref!r}")
    col = col_to_num(letters.upper())
    row = int(digits)
    if row < 1 or row > MAX_ROWS or col < 1 or col > MAX_COL:
        raise ValueError(f"invalid reference: {ref!r}")
    return row, col


def _ref_text(row: int, col: int) -> str:
    return f"{num_to_col(col)}{row}"


class _ParseSyntax(Exception):
    pass


class _EvalErr(Exception):
    def __init__(self, code):
        self.code = code


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

class _Tok:
    __slots__ = ("kind", "text", "value")

    def __init__(self, kind, text, value=None):
        self.kind = kind
        self.text = text
        self.value = value


_NUMBER_RE = re.compile(
    r"[0-9]+(?:\.[0-9]*)?(?:[eE][+-]?[0-9]+)?|\.[0-9]+(?:[eE][+-]?[0-9]+)?"
)
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def tokenize(src: str) -> list[_Tok]:
    toks: list[_Tok] = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c in _WS:
            i += 1
            continue
        if c == '"':
            i += 1
            buf: list[str] = []
            closed = False
            while i < n:
                if src[i] == '"':
                    if i + 1 < n and src[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                else:
                    buf.append(src[i])
                    i += 1
            if not closed:
                raise _ParseSyntax()
            toks.append(_Tok("string", "".join(buf)))
            continue
        if c.isdigit() or (c == "." and i + 1 < n and src[i + 1].isdigit()):
            m = _NUMBER_RE.match(src, i)
            toks.append(_Tok("number", m.group(0), float(m.group(0))))
            i = m.end()
            continue
        if c.isalpha() or c == "_":
            m = _IDENT_RE.match(src, i)
            word = m.group(0)
            i = m.end()
            up = word.upper()
            if up == "TRUE":
                toks.append(_Tok("bool", word, True))
            elif up == "FALSE":
                toks.append(_Tok("bool", word, False))
            elif _REF_RE.match(word):
                # In-bounds refs become "ref"; out-of-bounds ref-shaped tokens
                # stay as identifiers so evaluation can yield #REF!.
                try:
                    parse_ref(word)
                    toks.append(_Tok("ref", word.upper()))
                except ValueError:
                    toks.append(_Tok("ident", word))
            else:
                toks.append(_Tok("ident", word))
            continue
        two = src[i:i + 2]
        if two in ("<>", "<=", ">="):
            toks.append(_Tok("op", two))
            i += 2
            continue
        if c in "=<>+-*/&^(),:":
            toks.append(_Tok("op", c))
            i += 1
            continue
        raise _ParseSyntax()
    return toks


# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------

class _Num:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Str:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Bool:
    __slots__ = ("v",)

    def __init__(self, v):
        self.v = v


class _Cell:
    __slots__ = ("ref",)

    def __init__(self, ref):
        self.ref = ref


class _Range:
    __slots__ = ("a", "b")

    def __init__(self, a, b):
        self.a = a
        self.b = b


class _Call:
    __slots__ = ("name", "args")

    def __init__(self, name, args):
        self.name = name
        self.args = args


class _Bin:
    __slots__ = ("op", "l", "r")

    def __init__(self, op, l, r):
        self.op = op
        self.l = l
        self.r = r


class _Un:
    __slots__ = ("op", "x")

    def __init__(self, op, x):
        self.op = op
        self.x = x


class _BadRef:
    __slots__ = ("ref",)

    def __init__(self, ref):
        self.ref = ref


class _BadName:
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

class _Parser:
    """Precedence (low -> high): comparison, &, +- , * /, unary, ^, primary.

    Unary sits above multiplicative but below power, so `-2^2` parses as
    -(2^2) = -4 and `2^-1` parses as 2^(-1) = 0.5. `^` is right-associative.
    All other binary levels are left-associative.
    """

    def __init__(self, toks: list[_Tok]):
        self.toks = toks
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def next(self) -> _Tok:
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        self.i += 1
        return t

    def at_op(self, *ops: str) -> bool:
        t = self.peek()
        return t is not None and t.kind == "op" and t.text in ops

    def expect_op(self, op: str) -> None:
        t = self.peek()
        if t is None or t.kind != "op" or t.text != op:
            raise _ParseSyntax()
        self.i += 1

    def parse(self):
        node = self.concat()
        while self.at_op("=", "<>", "<", ">", "<=", ">="):
            op = self.next().text
            node = _Bin(op, node, self.concat())
        return node

    def concat(self):
        node = self.additive()
        while self.at_op("&"):
            self.next()
            node = _Bin("&", node, self.additive())
        return node

    def additive(self):
        node = self.multiplicative()
        while self.at_op("+", "-"):
            op = self.next().text
            node = _Bin(op, node, self.multiplicative())
        return node

    def multiplicative(self):
        node = self.unary()
        while self.at_op("*", "/"):
            op = self.next().text
            node = _Bin(op, node, self.unary())
        return node

    def unary(self):
        if self.at_op("-", "+"):
            op = self.next().text
            return _Un(op, self.unary())
        return self.power()

    def power(self):
        base = self.primary()
        if self.at_op("^"):
            self.next()
            return _Bin("^", base, self.unary())
        return base

    def primary(self):
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        if t.kind == "number":
            self.next()
            return _Num(t.value)
        if t.kind == "string":
            self.next()
            return _Str(t.value)
        if t.kind == "bool":
            self.next()
            return _Bool(t.value)
        if t.kind == "ref":
            self.next()
            row, col = parse_ref(t.text)
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == ":":
                self.next()
                t2 = self.next()
                if t2.kind != "ref":
                    raise _ParseSyntax()
                row2, col2 = parse_ref(t2.text)
                return _Range((row, col), (row2, col2))
            return _Cell((row, col))
        if t.kind == "ident":
            self.next()
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == "(":
                self.next()
                args: list = []
                if self.at_op(")"):
                    self.next()
                else:
                    args.append(self.arg())
                    while self.at_op(","):
                        self.next()
                        args.append(self.arg())
                    self.expect_op(")")
                return _Call(t.text.upper(), args)
            if _REF_RE.match(t.text):
                # Reference-shaped but out of bounds -> #REF! at evaluation.
                return _BadRef(t.text.upper())
            return _BadName(t.text)
        if t.kind == "op" and t.text == "(":
            self.next()
            node = self.parse()
            self.expect_op(")")
            return node
        raise _ParseSyntax()

    def arg(self):
        """An argument may be a range (A1:B3) or a full expression."""
        t = self.peek()
        if t is None:
            raise _ParseSyntax()
        if t.kind == "ref":
            save = self.i
            self.next()
            nxt = self.peek()
            if nxt is not None and nxt.kind == "op" and nxt.text == ":":
                self.next()
                t2 = self.next()
                if t2.kind != "ref":
                    raise _ParseSyntax()
                row, col = parse_ref(t.text)
                row2, col2 = parse_ref(t2.text)
                return _Range((row, col), (row2, col2))
            self.i = save
        return self.parse()


def parse_formula(expr: str):
    toks = tokenize(expr)
    if not toks:
        raise _ParseSyntax()
    p = _Parser(toks)
    node = p.parse()
    if p.i != len(toks):
        raise _ParseSyntax()
    return node


# ---------------------------------------------------------------------------
# Coercion helpers
# ---------------------------------------------------------------------------

def _is_num(v) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _finite(v):
    f = float(v)
    if not math.isfinite(f):
        return VALUE_E
    return f


def _to_number(v):
    """Arithmetic coercion: number -> itself, bool -> 1/0, empty -> 0, text -> error."""
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, (int, float)):
        return float(v)
    return VALUE_E


def _to_text(v) -> str:
    if v is None:
        return ""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, (int, float)):
        f = float(v)
        if math.isfinite(f) and f == int(f) and abs(f) < 1e15:
            return str(int(f))
        return repr(f)
    if isinstance(v, str):
        return v
    return str(v)


def _round_half_away(x: float, digits: int):
    if not math.isfinite(x):
        return VALUE_E
    d = Decimal(repr(x))
    q = Decimal(1).scaleb(-digits)  # 10^-digits
    with localcontext() as ctx:
        ctx.prec = 60
        scaled = d / q
        if scaled >= 0:
            fl = scaled.to_integral_value(rounding="ROUND_FLOOR")
            choice = fl + 1 if (scaled - fl) >= Decimal("0.5") else fl
        else:
            ce = scaled.to_integral_value(rounding="ROUND_CEILING")
            choice = ce - 1 if (ce - scaled) >= Decimal("0.5") else ce
        result = choice * q
    return float(result)


# ---------------------------------------------------------------------------
# Sheet
# ---------------------------------------------------------------------------

class Sheet:
    def __init__(self):
        self._raw: dict[tuple[int, int], str] = {}
        self._ast_cache: dict[tuple[int, int], object] = {}
        self._parse_fail: set[tuple[int, int]] = set()
        self._undo_stack: list[tuple[tuple[int, int], str | None]] = []
        self._values: dict[tuple[int, int], object] = {}
        self._direct_deps: dict[tuple[int, int], set[tuple[int, int]]] = {}
        self._direct_rdeps: dict[tuple[int, int], set[tuple[int, int]]] = {}
        self._computed = False

    # -- public API ---------------------------------------------------------

    def set(self, ref: str, raw: str) -> None:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")
        key = parse_ref(ref)
        old = self._raw.get(key)
        self._store(key, raw)
        self._undo_stack.append((key, old))
        self._rebuild_graph()
        self._recompute_all()

    def get_raw(self, ref) -> str | None:
        key = parse_ref(ref)
        return self._raw.get(key)

    def get(self, ref):
        key = parse_ref(ref)
        if key not in self._raw:
            return None
        if not self._computed:
            self._recompute_all()
        return self._values.get(key)

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        key, old = self._undo_stack.pop()
        self._store(key, old if old is not None else "")
        self._rebuild_graph()
        self._recompute_all()
        return True

    def dependents(self, ref) -> list[str]:
        key = parse_ref(ref)
        seen: set[tuple[int, int]] = set()
        stack = [key]
        while stack:
            cur = stack.pop()
            for dep in self._direct_rdeps.get(cur, ()):
                if dep not in seen:
                    seen.add(dep)
                    stack.append(dep)
        seen.discard(key)
        return [_ref_text(r, c) for (r, c) in sorted(seen)]

    def to_csv(self) -> str:
        if not self._raw:
            return ""
        max_row = max(r for (r, _) in self._raw)
        max_col = max(c for (_, c) in self._raw)
        lines = []
        for r in range(1, max_row + 1):
            fields = []
            for c in range(1, max_col + 1):
                v = self.get(_ref_text(r, c))
                fields.append(_csv_field(_to_text(v)))
            lines.append(",".join(fields))
        return "\n".join(lines)

    # -- storage ------------------------------------------------------------

    def _store(self, key, raw: str) -> None:
        if raw == "":
            self._raw.pop(key, None)
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)
            return
        self._raw[key] = raw
        if raw.startswith("="):
            try:
                self._ast_cache[key] = parse_formula(raw[1:])
                self._parse_fail.discard(key)
            except _ParseSyntax:
                self._ast_cache.pop(key, None)
                self._parse_fail.add(key)
        else:
            self._ast_cache.pop(key, None)
            self._parse_fail.discard(key)

    # -- dependency graph ---------------------------------------------------

    def _rebuild_graph(self) -> None:
        self._direct_deps = {}
        self._direct_rdeps = {}
        for key, ast in self._ast_cache.items():
            deps: set[tuple[int, int]] = set()
            stack = [ast]
            while stack:
                node = stack.pop()
                if isinstance(node, _Cell):
                    deps.add(node.ref)
                elif isinstance(node, _Range):
                    (r1, c1), (r2, c2) = node.a, node.b
                    r1, r2 = min(r1, r2), max(r1, r2)
                    c1, c2 = min(c1, c2), max(c1, c2)
                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            deps.add((r, c))
                elif isinstance(node, _Un):
                    stack.append(node.x)
                elif isinstance(node, _Bin):
                    stack.append(node.l)
                    stack.append(node.r)
                elif isinstance(node, _Call):
                    stack.extend(node.args)
            deps.discard(key)
            self._direct_deps[key] = deps
            for d in deps:
                self._direct_rdeps.setdefault(d, set()).add(key)

    def _find_cycle_members(self) -> set[tuple[int, int]]:
        """Cells that belong to a circular reference (iterative Tarjan SCC)."""
        formula_cells = set(self._ast_cache.keys())
        graph: dict[tuple[int, int], set[tuple[int, int]]] = {}
        for key in formula_cells:
            graph[key] = {d for d in self._direct_deps.get(key, ()) if d in formula_cells}
        index_counter = [0]
        stack: list[tuple[int, int]] = []
        on_stack: set[tuple[int, int]] = set()
        index: dict[tuple[int, int], int] = {}
        lowlink: dict[tuple[int, int], int] = {}
        result: set[tuple[int, int]] = set()
        for start in sorted(graph):
            if start in index:
                continue
            work: list[tuple[tuple[int, int], iter]] = [(start, iter(sorted(graph[start])))]
            index[start] = lowlink[start] = index_counter[0]
            index_counter[0] += 1
            stack.append(start)
            on_stack.add(start)
            while work:
                v, it = work[-1]
                advanced = False
                for w in it:
                    if w not in index:
                        index[w] = lowlink[w] = index_counter[0]
                        index_counter[0] += 1
                        stack.append(w)
                        on_stack.add(w)
                        work.append((w, iter(sorted(graph[w]))))
                        advanced = True
                        break
                    elif w in on_stack:
                        lowlink[v] = min(lowlink[v], index[w])
                if advanced:
                    continue
                work.pop()
                if work:
                    pv = work[-1][0]
                    lowlink[pv] = min(lowlink[pv], lowlink[v])
                if lowlink[v] == index[v]:
                    scc: list[tuple[int, int]] = []
                    while True:
                        w = stack.pop()
                        on_stack.discard(w)
                        scc.append(w)
                        if w == v:
                            break
                    if len(scc) > 1:
                        result.update(scc)
                    elif scc[0] in graph[scc[0]]:
                        # Self-loop: =A1+1 in A1, or a range containing itself.
                        result.add(scc[0])
        return result

    # -- evaluation ---------------------------------------------------------

    def _recompute_all(self) -> None:
        cycle_members = self._find_cycle_members()
        values: dict[tuple[int, int], object] = {}
        formula_cells = set(self._ast_cache.keys())
        # Iterative post-order DFS over the dependency graph (cycle edges
        # naturally break because cycle members are overwritten afterwards;
        # ordering among cycle members is irrelevant since all get #CYCLE!).
        state: dict[tuple[int, int], int] = {}
        order: list[tuple[int, int]] = []
        for start in sorted(formula_cells):
            if state.get(start):
                continue
            work: list[tuple[tuple[int, int], bool]] = [(start, False)]
            while work:
                v, processed = work.pop()
                if processed:
                    order.append(v)
                    continue
                if state.get(v):
                    continue
                state[v] = 1
                work.append((v, True))
                for d in sorted(self._direct_deps.get(v, ())):
                    if d in formula_cells and not state.get(d):
                        work.append((d, False))
        for key in order:
            if key in cycle_members:
                values[key] = CYCLE_E
            else:
                values[key] = self._eval_ast(self._ast_cache[key], values, cycle_members)
        self._values = values
        self._computed = True

    def _cell_value(self, key, values, cycle_members):
        if key in cycle_members and key in self._ast_cache:
            return CYCLE_E
        if key in values:
            return values[key]
        if key in self._ast_cache:
            v = self._eval_ast(self._ast_cache[key], values, cycle_members)
            values[key] = v
            return v
        if key in self._parse_fail:
            return PARSE_E
        if key in self._raw:
            return self._literal_value(self._raw[key])
        return None

    def _literal_value(self, raw: str):
        s = raw.strip()
        if s == "":
            return raw
        try:
            f = float(s)
            if math.isfinite(f):
                return f
        except ValueError:
            pass
        return raw

    def _eval_ast(self, ast, values, cycle_members):
        try:
            return self._ev(ast, values, cycle_members)
        except _EvalErr as e:
            return e.code

    def _ev(self, node, values, cycle_members):
        if isinstance(node, (_Num, _Str, _Bool)):
            return node.v
        if isinstance(node, _Cell):
            return self._cell_value(node.ref, values, cycle_members)
        if isinstance(node, _BadRef):
            return REF_E
        if isinstance(node, _BadName):
            return NAME_E
        if isinstance(node, _Range):
            return VALUE_E  # range outside a function argument
        if isinstance(node, _Un):
            v = self._ev(node.x, values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            return _finite(-n if node.op == "-" else n)
        if isinstance(node, _Bin):
            return self._ev_bin(node, values, cycle_members)
        if isinstance(node, _Call):
            return self._ev_call(node, values, cycle_members)
        raise _EvalErr(VALUE_E)

    def _ev_bin(self, node, values, cycle_members):
        op = node.op
        l = self._ev(node.l, values, cycle_members)
        if isinstance(l, str) and l in ERROR_CODES:
            return l
        r = self._ev(node.r, values, cycle_members)
        if isinstance(r, str) and r in ERROR_CODES:
            return r
        if op in ("=", "<>", "<", ">", "<=", ">="):
            return self._compare(op, l, r)
        if op == "&":
            return _to_text(l) + _to_text(r)
        ln = _to_number(l)
        if isinstance(ln, str):
            return ln
        rn = _to_number(r)
        if isinstance(rn, str):
            return rn
        if op == "+":
            return _finite(ln + rn)
        if op == "-":
            return _finite(ln - rn)
        if op == "*":
            return _finite(ln * rn)
        if op == "/":
            if rn == 0.0:
                return DIV0
            return _finite(ln / rn)
        if op == "^":
            if ln == 0.0 and rn < 0:
                return DIV0
            try:
                res = ln ** rn
            except OverflowError:
                return VALUE_E
            except ZeroDivisionError:
                return DIV0
            if isinstance(res, complex):
                return VALUE_E
            return _finite(res)
        raise _EvalErr(VALUE_E)

    def _compare(self, op, l, r):
        ln = _is_num(l)
        rn = _is_num(r)
        if isinstance(l, bool) and rn:
            a, b = (1.0 if l else 0.0), float(r)
        elif ln and isinstance(r, bool):
            a, b = float(l), (1.0 if r else 0.0)
        elif isinstance(l, bool) and isinstance(r, bool):
            a, b = (1.0 if l else 0.0), (1.0 if r else 0.0)
        elif ln and rn:
            a, b = float(l), float(r)
        elif isinstance(l, str) and isinstance(r, str):
            a, b = l.casefold(), r.casefold()
        elif l is None and rn:
            a, b = 0.0, float(r)
        elif l is None and isinstance(r, bool):
            a, b = 0.0, (1.0 if r else 0.0)
        elif r is None and ln:
            a, b = float(l), 0.0
        elif r is None and isinstance(l, bool):
            a, b = (1.0 if l else 0.0), 0.0
        elif l is None and isinstance(r, str):
            a, b = "", r
        elif isinstance(l, str) and r is None:
            a, b = l, ""
        else:
            return VALUE_E
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == ">":
            return a > b
        if op == "<=":
            return a <= b
        return a >= b

    def _range_values(self, rng, values, cycle_members):
        (r1, c1), (r2, c2) = rng.a, rng.b
        r1, r2 = min(r1, r2), max(r1, r2)
        c1, c2 = min(c1, c2), max(c1, c2)
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                yield self._cell_value((r, c), values, cycle_members)

    def _ev_call(self, node, values, cycle_members):
        name = node.name
        args = node.args
        if name == "IF":
            if len(args) == 1 or len(args) >= 4:
                raise _EvalErr(VALUE_E)
            cond = self._ev(args[0], values, cycle_members)
            if isinstance(cond, str) and cond in ERROR_CODES:
                return cond
            if isinstance(cond, str):
                raise _EvalErr(VALUE_E)
            truth = bool(cond) if isinstance(cond, bool) else (_to_number(cond) != 0)
            if truth:
                return self._ev(args[1], values, cycle_members)
            if len(args) == 3:
                return self._ev(args[2], values, cycle_members)
            return False
        if name == "COUNT":
            count = 0
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if _is_num(v):
                            count += 1
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        continue
                    if v is None or isinstance(v, bool) or _is_num(v):
                        count += 1
            return float(count)
        if name in ("SUM", "AVERAGE", "MIN", "MAX"):
            nums: list[float] = []
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if isinstance(v, str) and v in ERROR_CODES:
                            return v
                        if _is_num(v):
                            nums.append(float(v))
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        return v
                    if v is None:
                        nums.append(0.0)
                    elif isinstance(v, bool):
                        nums.append(1.0 if v else 0.0)
                    elif _is_num(v):
                        nums.append(float(v))
                    else:
                        raise _EvalErr(VALUE_E)
            if name == "SUM":
                return _finite(math.fsum(nums))
            if name == "AVERAGE":
                if not nums:
                    return DIV0
                return _finite(math.fsum(nums) / len(nums))
            if name == "MIN":
                return _finite(min(nums)) if nums else 0.0
            return _finite(max(nums)) if nums else 0.0
        if name == "CONCAT":
            parts: list[str] = []
            for a in args:
                if isinstance(a, _Range):
                    for v in self._range_values(a, values, cycle_members):
                        if isinstance(v, str) and v in ERROR_CODES:
                            return v
                        parts.append(_to_text(v))
                else:
                    v = self._ev(a, values, cycle_members)
                    if isinstance(v, str) and v in ERROR_CODES:
                        return v
                    parts.append(_to_text(v))
            return "".join(parts)
        if name == "LEN":
            if len(args) != 1:
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            return float(len(_to_text(v)))
        if name == "ABS":
            if len(args) != 1:
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            return _finite(abs(n))
        if name == "ROUND":
            if len(args) not in (1, 2):
                raise _EvalErr(VALUE_E)
            v = self._ev(args[0], values, cycle_members)
            if isinstance(v, str) and v in ERROR_CODES:
                return v
            n = _to_number(v)
            if isinstance(n, str):
                return n
            digits = 0
            if len(args) == 2:
                dv = self._ev(args[1], values, cycle_members)
                if isinstance(dv, str) and dv in ERROR_CODES:
                    return dv
                dn = _to_number(dv)
                if isinstance(dn, str):
                    return dn
                digits = int(dn)  # truncated toward zero
            return _round_half_away(n, digits)
        return NAME_E


# ---------------------------------------------------------------------------
# CSV helpers
# ---------------------------------------------------------------------------

def _csv_field(text: str) -> str:
    if any(ch in text for ch in ",\"\n"):
        return '"' + text.replace('"', '""') + '"'
    return text
